using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class GoalView:MonoBehaviour {
  GameRuntime game;string mode="hardware",signature;Text current;float nextUpdate;
  public void Initialize(GameRuntime runtime){game=runtime;Build();}
  string Signature()=>mode+"|"+game.State.Settings.language+"|"+game.State.Workshop.revision+"|"+game.State.Prestige.revision+"|"+game.State.Hardware.Sum()+"|"+game.State.Research.Sum()+"|"+(game.State.Guidance.hasPinned?game.State.Guidance.pinned.kind+game.State.Guidance.pinned.id+game.State.Guidance.pinned.target:"");
  void Update(){if(game==null)return;if(Signature()!=signature)Build();if(Time.unscaledTime>=nextUpdate){Current();nextUpdate=Time.unscaledTime+.25f;}}
  Text Paragraph(string name,string value){var t=WorkshopUIFactory.Label(name,transform,value,14,54);t.supportRichText=false;t.alignment=TextAnchor.UpperLeft;t.GetComponent<LayoutElement>().preferredHeight=-1;return t;}
  void Current(){var q=GuidanceRules.Next(game.State);current.text=q.Title+"\n"+q.Progress+(q.HasCost?"\n"+q.Cost+" · missing "+q.MissingAmount:"")+(q.Eta>=0?" · ETA "+q.Eta.ToString("F1",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" s":"")+"\n"+q.Missing+(q.LegacyResearchQuote?"\nSource goal quote differs from current start quote: "+q.ActualCost+" Data":"")+"\n"+q.Benefit;}
  void Build(){signature=Signature();WorkshopUIFactory.Clear(transform);WorkshopUIFactory.Label("GoalsTitle",transform,"Next goal / pinned goals",18,54);current=Paragraph("CurrentGoal","");Current();WorkshopUIFactory.Button("GoToCurrentGoal",transform,"Show target",()=>game.NavigateGoal(GuidanceRules.Next(game.State)));var clear=WorkshopUIFactory.Button("ClearPinnedGoal",transform,"Unpin goal",()=>game.Act(s=>GuidanceRules.Pin(s,null),"goal-pin"));clear.interactable=game.Writable&&game.State.Guidance.hasPinned;Paragraph("GoalRules","Pinning only tracks progress and navigation. It never buys or claims rewards.");foreach(string kind in GuidanceRules.Kinds){string chosen=kind;WorkshopUIFactory.Button("GoalKind-"+kind,transform,(mode==kind?"● ":"")+new[]{"Hardware","Research","Blueprints","INT nodes","Craft items","Upgrade items","Blueprint mastery"}[Array.IndexOf(GuidanceRules.Kinds,kind)],()=>{mode=chosen;Build();});}foreach(var candidate in GuidanceRules.Candidates(game.State).Where(p=>p.kind==mode)){var pin=candidate.Copy();var q=GuidanceRules.Resolve(game.State,pin);if(q==null)continue;WorkshopUIFactory.Button("PinGoal-"+pin.kind+"-"+pin.id,transform,q.Title+" · "+q.Progress,()=>{game.Act(s=>GuidanceRules.Pin(s,pin),"goal-pin");Build();}).interactable=game.Writable;}}
 }
}
